cost = {"본점": 1000, "IT센터": 400, "A점": 0, "B점": 0}
rules = [("본점", {"IT센터": 0.2, "A점": 0.5, "B점": 0.3}),
         ("IT센터", {"A점": 0.6, "B점": 0.4})]
for src, ratio in rules:
    amt = cost[src]; cost[src] = 0
    for dst, r in ratio.items():
        cost[dst] += amt * r
    print(src, "배부 후", {k: round(v) for k, v in cost.items()})
print("합계 그대로?", round(sum(cost.values())) == 1400)
# 본점 배부 후 {'본점': 0, 'IT센터': 600, 'A점': 500, 'B점': 300}
# IT센터 배부 후 {'본점': 0, 'IT센터': 0, 'A점': 860, 'B점': 540}
# 합계 그대로? True

